insert into cpl_memory (slug,kind,title,summary,tags,status,source,verified_by,verified_at,author,event_date) values
('sam-first-display-run-explicit-go-2026-11-12','decision','Sam: the first live run of the new display apply waits for his explicit go','Sam via COBIx (#3111 6840755612, 5:09 PM PT 2026-11-12), COBIx''s wording: "the first live run of the new display apply goes out on Sam''s explicit go. After that first run, his 2026-10-10 standing go covers a display apply that follows a load that passed its checks. Each run still posts its confirmed record, rollback receipt and display minutes on the run-health line."',array['program-requirements','decision'],'verified','Sam, relayed by COBIx, #3111 comment 6840755612 (COBIx''s wording)','Sam Lee',now(),'SkyWren (S644)',date '2026-11-13'),
('d-santiago-canyon-display-held-s644','decision','Santiago Canyon''s display is held: its PDF files a transfer degree under the wrong control number','The S644 conductor, 2026-11-13, by the rule agreed with COBIx: his spot-check on #3194 found 2 of 5 Santiago Canyon records differ; its PDF prints Control Number after each program, so a transfer degree files under the preceding local degree. Display held; the 192 live rows stay, unchecked; reader fix and reread next.',array['program-requirements','decision'],'proposed','Session call, S644 (SkyWren, the conductor); PR 3194 comment 6841001207; #3111 comment 6841073592',null,null,'SkyWren (S644)',date '2026-11-13'),
('sam-first-display-run-go-2026-11-12','decision','Sam: go for the first live run of the display apply','Sam via COBIx (#3111 comment 6842097699; COBIx chat 6:33 PM PT 2026-11-12): go for the first live run of the #3190 display apply. Post the record, the receipt and the minutes on #3111. Santiago Canyon stays held.',array['program-requirements','decision'],'verified','Sam, relayed by COBIx, #3111 comment 6842097699','Sam Lee',now(),'SkyFinch (S645)',date '2026-11-12'),
('sam-glendale-unpark-2026-11-12','decision','Sam: unpark Glendale for its 2026-27 Coursedog catalog','Sam via COBIx (#3111 comment 6842097699, 6:33 PM PT 2026-11-12): unpark Glendale, read its 2026-27 Coursedog catalog, and update its registry row.',array['program-requirements','decision'],'verified','Sam, relayed by COBIx, #3111 comment 6842097699','Sam Lee',now(),'SkyFinch (S645)',date '2026-11-12'),
('sam-district-profiles-vision-2026-11-12','decision','Sam: a profile per CCC district, 72 plus Calbright','Sam via COBIx on #3198 (2026-11-12): district profiles cover the 72 CCC districts plus Calbright, each learning its SIS, CMS and CPL coding; the scout and wave-check bots are phase 1.',array['program-requirements','commons','decision'],'verified','Sam, relayed by COBIx, issue 3198','Sam Lee',now(),'SkyFinch (S645)',date '2026-11-12'),
('sam-banner-pilot-citrus-2026-11-12','decision','Sam: the three SIS pilots are Los Angeles CCD, Citrus and Riverside CCD','Sam via COBIx on #3198 (2026-11-12): the district-profile SIS pilots are Los Angeles CCD, Citrus and Riverside CCD.',array['program-requirements','commons','decision'],'verified','Sam, relayed by COBIx, issue 3198','Sam Lee',now(),'SkyFinch (S645)',date '2026-11-12')
insert into cpl_memory (slug,kind,title,summary,tags,status,source,verified_by,verified_at,author,event_date) values
('d-display-first-run-one-college-s645','decision','A new apply runs live on one college first, then the whole build','The S645 conductor: step=display writes the whole build, so #3204 added display_college. Run 43358665534 wrote North Orange Continuing Education alone (78 of 78); once the live count matched, run 43358971128 wrote the whole build 38a0fd8ed41f (17,595 written, 3 missing, 0 errors). Each applied record is the rollback.',array['program-requirements','decision'],'proposed','Session call, S645 (SkyFinch, the conductor); docs/reference/lanes/program-requirements-harvest.md; PR 3204',null,null,'SkyFinch (S645)',date '2026-11-13'),
('d-pdf-reader-number-line-design-s645','decision','The PDF reader binds by the printed number line where a college gates it','The S645 conductor (#3201, decisions 13 and 14, two review rounds): reading the number after a program is gated per college by its own evidence (Santiago Canyon 182 after, 0 before); in a uniform catalog the number line alone binds a block, refused only if its first strict heading names another listed program; an unprinted number is not_found; a filed record is never dropped.',array['program-requirements','decision'],'proposed','Session call, S645 (SkyFinch, the conductor); docs/reference/lanes/program-requirements-harvest.md; PR 3201',null,null,'SkyFinch (S645)',date '2026-11-13'),
('d-rescore-six-colleges-live-s645','decision','The #3193 rescore ran live at six colleges, a compare gate before each reread','The S645 conductor: reconcile, a compare gate against main, then reread with force at Coalinga, Grossmont, Pierce, Solano, San Bernardino Valley and ELAC: 126 rows replaced, 62 fail to pass, none pass to fail; the gate restored three record files from main (Solano 38591; ELAC 08252, 02430). Receipts carry before-values. The migration stays unapplied. #3207.',array['program-requirements','decision'],'proposed','Session call, S645 (SkyFinch, the conductor); docs/reference/lanes/program-requirements-harvest.md; PR 3207',null,null,'SkyFinch (S645)',date '2026-11-13'),
('d-district-profiles-files-first-s645','decision','District profiles start as repo files, before any table','The S645 conductor, answering COBIx on #3198: district profiles start as repo files COBIx writes on a branch, with a phase 0 builder after them; no Supabase table until the files show their shape. Pilots Los Angeles CCD, Citrus and Riverside CCD.',array['program-requirements','commons','decision'],'proposed','Session call, S645 (SkyFinch, the conductor); docs/reference/lanes/program-requirements-harvest.md; issue 3198',null,null,'SkyFinch (S645)',date '2026-11-13'),
('d-glendale-registry-coursedog-s645','decision','Glendales registry row and procedure record moved to its 2026-27 Coursedog catalog','The S645 conductor, on Sams go: Glendales registry row and procedure record v1 written 02:52Z 2026-11-13 (md5 47c9a5f92f56e985aaadbf2be9a2a236, was none); receipt and rollback on #3202. Its first capture listed 261 and read none; a fix (f02dcb9e) went out with a second capture.',array['program-requirements','decision'],'proposed','Session call, S645 (SkyFinch, the conductor); docs/reference/lanes/program-requirements-harvest.md; PR 3202',null,null,'SkyFinch (S645)',date '2026-11-13'),
('d-merge-is-publication-spot-check-first-s645','decision','Merging a college PR publishes its display build, so COBIx checks first','The S645 conductor: a college PRs display build is the pages data (cpl_pathways_roep_data.js on main, served by Pages), so merging it publishes. COBIxs five-record spot-check comes before the merge of #3205, #3206 and #3207.',array['program-requirements','decision'],'proposed','Session call, S645 (SkyFinch, the conductor); docs/reference/lanes/program-requirements-harvest.md',null,null,'SkyFinch (S645)',date '2026-11-13'),
('d-dv-sjcc-loaded-s645','decision','Diablo Valley and San Jose City loaded, unchecked','The S645 conductor, under the $40 go: Diablo Valley paid read $5.63, load inserted 88 of 90 (08013, 41233 place none of their courses; #3205); San Jose City paid read $6.63, load inserted 77 of 84 (#3206). Insert-only; each receipt is the rollback. Both wait on COBIxs spot-check before merge.',array['program-requirements','decision'],'proposed','Session call, S645 (SkyFinch, the conductor); docs/reference/lanes/program-requirements-harvest.md; PRs 3205, 3206',null,null,'SkyFinch (S645)',date '2026-11-13'),
('p-snapshot-check-couples-college-prs-s645','pitfall','A --check on a committed snapshot couples every college PR','S645 (#3201): regenerating and checking a 335 KB committed snapshot in each filing workflow would make every college PR conflict on it, and an unguarded step after a paid extraction could lose records. Write such a snapshot from a dispatch-only workflow, as the gap census does.',array['program-requirements','pitfall'],'proposed','S645, PR 3201',null,null,'SkyFinch (S645)',date '2026-11-13'),
('p-title-test-refuses-uniform-catalog-s645','pitfall','A title test refuses right blocks in a catalog whose number lines vote one way','S645 (#3201): Santiago Canyons proof capture refused 17 passing records on a title test; 16 held the right record. Where every number line votes the same way, bind by the number line and refuse only on another listed programs heading.',array['program-requirements','pitfall'],'proposed','S645, PR 3201, run 43360377086',null,null,'SkyFinch (S645)',date '2026-11-13'),
('p-dated-reads-need-main-refresh-s645','pitfall','A dated-reads job fails its verify unless the branch carries mains refresh','S645: Diablo Valleys dated reads (run 43357156084) failed at verify because the branchs Cuesta read predated #3200s refresh. Merge main into the college branch before dispatching its dated reads.',array['program-requirements','pitfall'],'proposed','S645, run 43357156084',null,null,'SkyFinch (S645)',date '2026-11-13'),
('p-wave-over-filed-colleges-extracts-nothing-s645','pitfall','A wave over colleges whose records are all filed extracts nothing','S645: wave s645a (run 43353563993) found Feather River and Palo Verde with nothing to extract, every record already filed, and Copper Mountain held again. Read the gap census before naming a waves colleges.',array['program-requirements','pitfall'],'proposed','S645, run 43353563993',null,null,'SkyFinch (S645)',date '2026-11-13'),
('p-display-step-writes-whole-build-s645','pitfall','step=display writes the whole build, whatever college is named','S645: before #3204 step=display ignored college and ran a bare --apply on the refs build, writing every row (the skip test is the build stamp). Name one college with display_college for a first or narrow run.',array['program-requirements','pitfall'],'proposed','S645, PR 3204',null,null,'SkyFinch (S645)',date '2026-11-13'),
('sam-sql-approve-fyi-2026-11-13','fact','Sam: an SQL approval prompt reached him with execute_sql allowed','Sam, in session S645 about 02:55Z 2026-11-13, verbatim: "FYI got an sql approve request you should have with for already". execute_sql was on the allow list at the session root and in the repo. Recorded in docs/reference/approval_prompt_hooks.md.',array['conductor','permissions','fact'],'verified','Sam, in session S645 (verbatim)','Sam Lee',now(),'SkyFinch (S645)',date '2026-11-13')
